begin;
-- Separate, additive multiplayer mode. No Classic records are modified.
create schema if not exists galactic_private;
revoke all on schema galactic_private from public,anon,authenticated;
create table if not exists galactic_private.datasets(version text primary key,players jsonb not null check(jsonb_typeof(players)='array'),config jsonb not null,sources jsonb not null default '{}',active boolean not null default false,created_at timestamptz not null default clock_timestamp());
create unique index if not exists galactic_one_active_dataset on galactic_private.datasets(active) where active;
create table if not exists galactic_private.rooms(id uuid primary key default gen_random_uuid(),code text not null unique,host_id uuid not null references auth.users(id) on delete cascade,title text not null check(char_length(title) between 2 and 40),public boolean not null default false,capacity int not null check(capacity between 2 and 8),phase text not null default 'lobby' check(phase in ('lobby','draft','tournament','finished','cancelled')),dataset_version text not null references galactic_private.datasets(version),seed text not null default gen_random_uuid()::text,draft_order jsonb not null default '[]',pick_number int not null default 0,pick_deadline timestamptz,active_match uuid,next_match_at timestamptz,winner uuid,version bigint not null default 0,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp());
create table if not exists galactic_private.members(id uuid primary key default gen_random_uuid(),room_id uuid not null references galactic_private.rooms(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(name) between 2 and 40),team_name text not null check(char_length(team_name) between 2 and 30),formation text,tactic text,ready boolean not null default false,last_seen timestamptz not null default clock_timestamp(),joined_at timestamptz not null default clock_timestamp(),unique(room_id,user_id));
create index if not exists galactic_members_user on galactic_private.members(user_id);
create table if not exists galactic_private.picks(room_id uuid not null references galactic_private.rooms(id) on delete cascade,number int not null,member_id uuid not null references galactic_private.members(id) on delete cascade,player_id text not null,slot_id text not null,automatic boolean not null default false,picked_at timestamptz not null default clock_timestamp(),primary key(room_id,number),unique(room_id,player_id),unique(room_id,member_id,slot_id));
create index if not exists galactic_picks_member on galactic_private.picks(member_id);
create table if not exists galactic_private.matches(id uuid primary key default gen_random_uuid(),room_id uuid not null references galactic_private.rooms(id) on delete cascade,round int not null,slot int not null,source_home uuid,source_away uuid,home_id uuid,away_id uuid,status text not null default 'waiting' check(status in ('waiting','ready','live','finished','bye')),started_at timestamptz,ends_at timestamptz,timeline jsonb not null default '[]',home_score int not null default 0,away_score int not null default 0,winner_id uuid,penalties jsonb,stats jsonb,unique(room_id,round,slot));

create index if not exists galactic_rooms_host on galactic_private.rooms(host_id);
create index if not exists galactic_rooms_dataset on galactic_private.rooms(dataset_version);
create index if not exists galactic_public_lobbies on galactic_private.rooms(created_at desc) where public and phase='lobby';
alter table galactic_private.datasets enable row level security;
alter table galactic_private.rooms enable row level security;
alter table galactic_private.members enable row level security;
alter table galactic_private.picks enable row level security;
alter table galactic_private.matches enable row level security;
revoke all on all tables in schema galactic_private from public,anon,authenticated;
alter default privileges in schema galactic_private revoke execute on functions from public,anon,authenticated;
create or replace function galactic_private.random_value(seed text,n int) returns double precision language sql immutable set search_path='' as $$select (('x'||substr(md5(seed||':'||n),1,8))::bit(32)::bigint)::double precision/4294967296.0$$;
create or replace function galactic_private.require_user() returns uuid language plpgsql stable set search_path='' as $$declare u uuid:=auth.uid();begin if u is null then raise exception 'برای بازی کهکشانی وارد حساب شو.' using errcode='28000';end if;return u;end;$$;
create or replace function galactic_private.fit(positions jsonb,role text,config jsonb) returns numeric language plpgsql immutable set search_path='' as $$declare p text;best numeric:=.55;begin if positions?role then return 1;end if;if role='GK'then return .15;end if;if positions?'GK'then return .2;end if;for p in select jsonb_array_elements_text(positions)loop best:=greatest(best,coalesce((config#>>array['adjacency',p,role])::numeric,0));end loop;return best;end;$$;
create or replace function galactic_private.turn_member(r galactic_private.rooms) returns uuid language plpgsql immutable set search_path='' as $$declare n int:=jsonb_array_length(r.draft_order);idx int;begin if n=0 then return null;end if;idx:=r.pick_number%n;if (r.pick_number/n)%2=1 then idx:=n-1-idx;end if;return (r.draft_order->>idx)::uuid;end;$$;
create or replace function galactic_private.notify_room(rid uuid) returns void language plpgsql set search_path='' as $$begin if exists(select 1 from pg_namespace where nspname='realtime')then execute 'select realtime.send($1,$2,$3,true)'using jsonb_build_object('room',rid),'changed','galactic:'||rid::text;end if;end;$$;

create or replace function galactic_private.lineup(p_room uuid,p_member uuid) returns jsonb language plpgsql stable set search_path='' as $$
declare d galactic_private.datasets%rowtype;m galactic_private.members%rowtype;result jsonb;
begin
 select * into m from galactic_private.members where id=p_member and room_id=p_room;
 if m is null then return '[]';end if;
 select ds.* into d from galactic_private.datasets ds join galactic_private.rooms r on r.dataset_version=ds.version where r.id=p_room;
 select coalesce(jsonb_agg(player||jsonb_build_object('slot',pk.slot_id,'role',slot->>'role','x',slot->'x','y',slot->'y','fit',galactic_private.fit(player->'positions',slot->>'role',d.config),'effective',round((player->>'overall')::numeric*galactic_private.fit(player->'positions',slot->>'role',d.config)))order by ord),'[]')into result
 from galactic_private.picks pk cross join jsonb_array_elements(d.players)player cross join jsonb_array_elements(d.config#>array['formations',m.formation,'slots'])with ordinality ss(slot,ord)
 where pk.room_id=p_room and pk.member_id=p_member and player->>'id'=pk.player_id and slot->>'id'=pk.slot_id;
 return result;
end;$$;
create or replace function galactic_private.strength(p_room uuid,p_member uuid) returns jsonb language plpgsql stable set search_path='' as $$
declare p jsonb;players jsonb:=galactic_private.lineup(p_room,p_member);conf jsonb;tactic text;f numeric;dw numeric;mw numeric;aw numeric;ds numeric:=0;ms numeric:=0;ats numeric:=0;dc numeric:=0;mc numeric:=0;ac numeric:=0;gk numeric:=0;total numeric:=0;stamina numeric:=0;
begin
 select m.tactic,d.config into tactic,conf from galactic_private.members m join galactic_private.rooms r on r.id=m.room_id join galactic_private.datasets d on d.version=r.dataset_version where m.id=p_member and m.room_id=p_room;
 for p in select value from jsonb_array_elements(players)loop
  f:=(p->>'fit')::numeric;total:=total+(p->>'effective')::numeric;stamina:=stamina+(p->>'stamina')::numeric;
  if p->>'role'='GK'then gk:=(p->>'goalkeeping')::numeric*f;continue;end if;
  dw:=case p->>'role'when 'CB'then 1 when 'LB'then .8 when 'RB'then .8 when 'DM'then .6 when 'CM'then .2 else .05 end;
  mw:=case p->>'role'when 'DM'then 1.1 when 'CM'then 1 when 'AM'then .9 when 'LW'then .4 when 'RW'then .4 when 'LB'then .2 when 'RB'then .2 else .1 end;
  aw:=case p->>'role'when 'ST'then 1 when 'LW'then .8 when 'RW'then .8 when 'AM'then .65 when 'CM'then .3 else .1 end;
  ds:=ds+dw*f*((p->>'defending')::numeric*.6+(p->>'physical')::numeric*.25+(p->>'pace')::numeric*.15);dc:=dc+dw;
  ms:=ms+mw*f*((p->>'passing')::numeric*.5+(p->>'dribbling')::numeric*.35+(p->>'physical')::numeric*.15);mc:=mc+mw;
  ats:=ats+aw*f*((p->>'shooting')::numeric*.5+(p->>'dribbling')::numeric*.25+(p->>'pace')::numeric*.25);ac:=ac+aw;
 end loop;
 return jsonb_build_object('overall',round(total/11),'goalkeeping',round(gk),'defence',round(ds/greatest(dc,1)*least(1.08,greatest(.92,power(dc/3.6,.15)))*(conf#>>array['tactics',tactic,'defence'])::numeric),'midfield',round(ms/greatest(mc,1)*least(1.08,greatest(.92,power(mc/3.4,.15)))*(conf#>>array['tactics',tactic,'midfield'])::numeric),'attack',round(ats/greatest(ac,1)*least(1.08,greatest(.92,power(ac/3.2,.15)))*(conf#>>array['tactics',tactic,'attack'])::numeric),'stamina',round(stamina/11),'fatigue',(conf#>array['tactics',tactic,'fatigue']),'tactic',tactic);
end;$$;
create or replace function galactic_private.actor(players jsonb,seed text,n int,shooters boolean default true)returns jsonb language sql immutable set search_path='' as $$
 select p from jsonb_array_elements(players)with ordinality q(p,i) order by case when shooters and p->>'role'='GK'then 2 when shooters and p->>'role'not in('ST','LW','RW','AM')then 1 else 0 end,galactic_private.random_value(seed,n+i::int) limit 1
$$;
create or replace function galactic_private.make_match(p_match uuid,p_start timestamptz)returns void language plpgsql set search_path='' as $$
declare m galactic_private.matches%rowtype;r galactic_private.rooms%rowtype;hm galactic_private.members%rowtype;am galactic_private.members%rowtype;h jsonb;a jsonb;hl jsonb;al jsonb;raw jsonb:='[]';v_timeline jsonb:='[]';e jsonb;actor jsonb;keeper jsonb;seed text;idx int:=0;i int;minute int;prev_min int:=0;offset_ms bigint:=0;hold int;half boolean:=false;hs int:=0;ascore int:=0;side int;chance double precision;p_home double precision;fat_h double precision;fat_a double precision;kind text;txt text;hp int:=0;ap int:=0;ht int:=0;ataken int:=0;winner uuid;v_penalties jsonb;hshot jsonb;ashot jsonb;scored boolean;forced boolean;hpos numeric;v_extra boolean:=false;
begin
 select * into m from galactic_private.matches where id=p_match;select * into r from galactic_private.rooms where id=m.room_id;
 select * into hm from galactic_private.members where id=m.home_id;select * into am from galactic_private.members where id=m.away_id;
 h:=galactic_private.strength(r.id,hm.id);a:=galactic_private.strength(r.id,am.id);hl:=galactic_private.lineup(r.id,hm.id);al:=galactic_private.lineup(r.id,am.id);seed:=r.seed||':match:'||m.round||':'||m.slot;
 hpos:=least(.72,greatest(.28,.5+((h->>'midfield')::numeric-(a->>'midfield')::numeric)/150));
 raw:=raw||jsonb_build_array(jsonb_build_object('minute',0,'kind','kickoff','text','بازی «'||hm.team_name||'» و «'||am.team_name||'» آغاز شد.','homeScore',0,'awayScore',0));
 -- Regulation and extra-time chances use the same model. Quality changes the
 -- probabilities, while neutral ground and symmetric rules avoid host advantage.
 for i in 1..24 loop
  if i=19 then
   raw:=raw||jsonb_build_array(jsonb_build_object('minute',90,'kind','full_time','text',case when hs=ascore then 'نود دقیقه با تساوی تمام شد؛ بازی به وقت اضافه می‌رود.'else 'سوت پایان نود دقیقه به صدا درآمد.'end,'homeScore',hs,'awayScore',ascore));
   if hs<>ascore then exit;end if;
   v_extra:=true;
   raw:=raw||jsonb_build_array(jsonb_build_object('minute',90,'kind','extra_start','text','وقت اضافه آغاز شد؛ سی دقیقه برای تعیین برنده.','homeScore',hs,'awayScore',ascore));
  end if;
  minute:=case when i<=18 then floor(i*90.0/19)::int+floor(galactic_private.random_value(seed,i)*2)::int else 90+(i-18)*4 end;
  if not half and minute>=45 then raw:=raw||jsonb_build_array(jsonb_build_object('minute',45,'kind','halftime','text','پایان نیمهٔ اول؛ دو تیم برای نیمهٔ دوم آماده می‌شوند.','homeScore',hs,'awayScore',ascore));half:=true;end if;
  idx:=i*100;
  fat_h:=1-(h->>'fatigue')::double precision*least(minute,120)/90.0*(1.25-(h->>'stamina')::double precision/200);
  fat_a:=1-(a->>'fatigue')::double precision*least(minute,120)/90.0*(1.25-(a->>'stamina')::double precision/200);
  p_home:=least(.78,greatest(.22,.5+((h->>'midfield')::double precision*fat_h-(a->>'midfield')::double precision*fat_a)/150));
  if h->>'tactic'='counter'and p_home<.5 then p_home:=p_home+.05;end if;
  if a->>'tactic'='counter'and p_home>.5 then p_home:=p_home-.05;end if;
  side:=case when galactic_private.random_value(seed,idx+1)<p_home then 0 else 1 end;
  actor:=galactic_private.actor(case when side=0 then hl else al end,seed,idx+10,true);
  keeper:=galactic_private.actor(case when side=0 then al else hl end,seed,idx+20,false);
  if galactic_private.random_value(seed,idx+2)<.71 then
   chance:=least(.48,greatest(.06,.21+(case when side=0 then (h->>'attack')::double precision*fat_h-((a->>'defence')::double precision*.55+(a->>'goalkeeping')::double precision*.45)*fat_a else (a->>'attack')::double precision*fat_a-((h->>'defence')::double precision*.55+(h->>'goalkeeping')::double precision*.45)*fat_h end)/220));
   if galactic_private.random_value(seed,idx+3)<chance then
    kind:='goal';if side=0 then hs:=hs+1;else ascore:=ascore+1;end if;
    txt:=(actor->>'name')||case floor(galactic_private.random_value(seed,idx+4)*4)::int when 0 then ' با یک ضربهٔ دقیق توپ را به تور رساند!'when 1 then ' از فضای پشت دفاع استفاده کرد و گل زد!'when 2 then ' پاس هم‌تیمی‌اش را به گل تبدیل کرد!'else ' در محوطه صاحب توپ شد و دروازه را باز کرد!'end;
   elsif galactic_private.random_value(seed,idx+5)<.55 then kind:='save';txt:=(actor->>'name')||' شوت زد؛ دروازه‌بان با واکنش به‌موقع توپ را مهار کرد.';
   else kind:='chance';txt:=(actor->>'name')||' فرصت خوبی داشت، اما ضربه‌اش از کنار دروازه گذشت.';end if;
  elsif galactic_private.random_value(seed,idx+6)<.5 then kind:='interception';txt:='پاس به سمت '||(actor->>'name')||' رفت، اما مدافع حریف مسیر توپ را بست.';
  else kind:='corner';txt:='حرکت '||(actor->>'name')||' از کناره با دخالت دفاع به کرنر انجامید.';end if;
  raw:=raw||jsonb_build_array(jsonb_build_object('minute',minute,'kind',kind,'side',side,'text',txt,'homeScore',hs,'awayScore',ascore));
 end loop;
 if v_extra then
  raw:=raw||jsonb_build_array(jsonb_build_object('minute',120,'kind','extra_end','text',case when hs=ascore then 'وقت اضافه هم با تساوی تمام شد؛ نوبت ضربات پنالتی است.'else 'وقت اضافه به پایان رسید.'end,'homeScore',hs,'awayScore',ascore));
 end if;
 -- Extra time can finish with a winner; only a still-level score needs penalties.
 if hs=ascore then
  for i in 1..30 loop
   select p into hshot from jsonb_array_elements(hl)p order by (p->>'shooting')::int desc,p->>'id' offset((i-1)%11)limit 1;
   select p into ashot from jsonb_array_elements(al)p order by (p->>'shooting')::int desc,p->>'id' offset((i-1)%11)limit 1;
   scored:=galactic_private.random_value(seed,3000+i*2)<least(.9,greatest(.5,.74+((hshot->>'shooting')::double precision-(a->>'goalkeeping')::double precision)/500));forced:=scored;
   ht:=ht+1;if scored then hp:=hp+1;end if;
   raw:=raw||jsonb_build_array(jsonb_build_object('minute',120,'kind','penalty','side',0,'text',(hshot->>'name')||case when scored then ' پنالتی را گل کرد.'else ' پنالتی را از دست داد.'end,'homeScore',hs,'awayScore',ascore,'penaltyHome',hp,'penaltyAway',ap));
   if ht<=5 and ataken<=5 and(hp>ap+greatest(0,5-ataken)or ap>hp+greatest(0,5-ht))then exit;end if;
   scored:=case when i=30 then not forced else galactic_private.random_value(seed,3001+i*2)<least(.9,greatest(.5,.74+((ashot->>'shooting')::double precision-(h->>'goalkeeping')::double precision)/500))end;
   ataken:=ataken+1;if scored then ap:=ap+1;end if;
   raw:=raw||jsonb_build_array(jsonb_build_object('minute',120,'kind','penalty','side',1,'text',(ashot->>'name')||case when scored then ' پنالتی را گل کرد.'else ' پنالتی را از دست داد.'end,'homeScore',hs,'awayScore',ascore,'penaltyHome',hp,'penaltyAway',ap));
   if(ht=ataken and ht>=5 and hp<>ap)or(ht<=5 and ataken<=5 and(hp>ap+greatest(0,5-ataken)or ap>hp+greatest(0,5-ht)))then exit;end if;
  end loop;
  winner:=case when hp>ap then hm.id else am.id end;v_penalties:=jsonb_build_object('home',hp,'away',ap);
 else winner:=case when hs>ascore then hm.id else am.id end;end if;
 raw:=raw||jsonb_build_array(jsonb_build_object('minute',case when v_extra then 120 else 90 end,'kind','final','text','«'||case when winner=hm.id then hm.team_name else am.team_name end||'» برندهٔ مسابقه شد.','homeScore',hs,'awayScore',ascore,'penaltyHome',case when v_penalties is not null then hp end,'penaltyAway',case when v_penalties is not null then ap end));
 for e in select value from jsonb_array_elements(raw)loop
  offset_ms:=offset_ms+greatest(0,(e->>'minute')::int-prev_min)*2000;hold:=case e->>'kind'when 'halftime'then 8000 when 'penalty'then 4000 when 'kickoff'then 4000 when 'final'then 5000 else 6000 end;
  v_timeline:=v_timeline||jsonb_build_array(e||jsonb_build_object('atMs',offset_ms,'untilMs',offset_ms+hold));offset_ms:=offset_ms+hold;prev_min:=(e->>'minute')::int;
 end loop;
 update galactic_private.matches set status='live',started_at=p_start,ends_at=p_start+offset_ms*interval '1 millisecond',timeline=v_timeline,home_score=hs,away_score=ascore,winner_id=winner,penalties=v_penalties,stats=jsonb_build_object('home',h,'away',a,'homePossession',round(hpos*100),'awayPossession',100-round(hpos*100))where id=p_match;
 update galactic_private.rooms set active_match=p_match,next_match_at=null where id=r.id;
end;$$;

create or replace function galactic_private.create_bracket(p_room uuid,p_at timestamptz)returns void language plpgsql set search_path='' as $$
declare r galactic_private.rooms%rowtype;n int;size int:=2;ord int[]:=array[0,1];next_order int[];seed_no int;round_no int:=1;slots int;idx int;ids uuid[];previous_ids uuid[];new_ids uuid[];hid uuid;aid uuid;mid uuid;status text;
begin
 select * into r from galactic_private.rooms where id=p_room;n:=jsonb_array_length(r.draft_order);
 select array_agg(m.id order by galactic_private.random_value(r.seed||':bracket:'||m.id,1))into ids from galactic_private.members m where m.room_id=p_room;
 while size<n loop size:=size*2;next_order:='{}';foreach seed_no in array ord loop next_order:=next_order||array[seed_no,size-1-seed_no];end loop;ord:=next_order;end loop;
 slots:=size/2;previous_ids:='{}';
 for idx in 1..slots loop
  hid:=ids[ord[idx*2-1]+1];aid:=ids[ord[idx*2]+1];mid:=gen_random_uuid();status:=case when hid is null or aid is null then 'bye'else 'ready'end;
  insert into galactic_private.matches(id,room_id,round,slot,home_id,away_id,status,winner_id)values(mid,p_room,1,idx,hid,aid,status,case when status='bye'then coalesce(hid,aid)end);previous_ids:=array_append(previous_ids,mid);
 end loop;
 while slots>1 loop round_no:=round_no+1;slots:=slots/2;new_ids:='{}';for idx in 1..slots loop mid:=gen_random_uuid();insert into galactic_private.matches(id,room_id,round,slot,source_home,source_away)values(mid,p_room,round_no,idx,previous_ids[idx*2-1],previous_ids[idx*2]);new_ids:=array_append(new_ids,mid);end loop;previous_ids:=new_ids;end loop;
 update galactic_private.rooms set phase='tournament',pick_deadline=null,next_match_at=p_at+interval '10 seconds'where id=p_room;
end;$$;
create or replace function galactic_private.do_pick(p_room uuid,p_member uuid,p_player text,p_slot text,p_auto boolean,p_at timestamptz)returns void language plpgsql set search_path='' as $$
declare r galactic_private.rooms%rowtype;
begin
 select * into r from galactic_private.rooms where id=p_room;
 insert into galactic_private.picks(room_id,number,member_id,player_id,slot_id,automatic,picked_at)values(p_room,r.pick_number,p_member,p_player,p_slot,p_auto,p_at);
 update galactic_private.rooms set pick_number=pick_number+1,pick_deadline=p_at+interval '60 seconds'where id=p_room;
 if r.pick_number+1=jsonb_array_length(r.draft_order)*11 then perform galactic_private.create_bracket(p_room,p_at);end if;
end;$$;
create or replace function galactic_private.auto_pick(p_room uuid,p_at timestamptz)returns void language plpgsql set search_path='' as $$
declare r galactic_private.rooms%rowtype;d galactic_private.datasets%rowtype;who uuid;formation text;player_id text;slot_id text;
begin
 select * into r from galactic_private.rooms where id=p_room;select * into d from galactic_private.datasets where version=r.dataset_version;who:=galactic_private.turn_member(r);
 select m.formation into formation from galactic_private.members m where m.id=who;
 select p->>'id',s->>'id'into player_id,slot_id from jsonb_array_elements(d.players)p cross join jsonb_array_elements(d.config#>array['formations',formation,'slots'])s
 where not exists(select 1 from galactic_private.picks pk where pk.room_id=p_room and pk.player_id=p->>'id')and not exists(select 1 from galactic_private.picks pk where pk.room_id=p_room and pk.member_id=who and pk.slot_id=s->>'id')
 order by case when s->>'role'='GK'and galactic_private.fit(p->'positions','GK',d.config)=1 then 0 else 1 end,((p->>'overall')::numeric*galactic_private.fit(p->'positions',s->>'role',d.config))desc,p->>'id',s->>'id'limit 1;
 if player_id is null then raise exception 'بازیکن کافی برای تکمیل تیم وجود ندارد.';end if;
 perform galactic_private.do_pick(p_room,who,player_id,slot_id,true,p_at);
end;$$;
create or replace function galactic_private.advance(p_room uuid,p_now timestamptz)returns boolean language plpgsql set search_path='' as $$
declare r galactic_private.rooms%rowtype;m galactic_private.matches%rowtype;s1 galactic_private.matches%rowtype;s2 galactic_private.matches%rowtype;w galactic_private.matches%rowtype;changed boolean:=false;iteration int;
begin
 for iteration in 1..128 loop
  select * into r from galactic_private.rooms where id=p_room;
  if r.phase='draft'then
   if r.pick_deadline<=p_now then perform galactic_private.auto_pick(p_room,r.pick_deadline);changed:=true;continue;end if;exit;
  elsif r.phase='tournament'then
   if r.active_match is not null then
    select * into m from galactic_private.matches where id=r.active_match;
    if m.status='live'then if m.ends_at>p_now then exit;end if;update galactic_private.matches set status='finished'where id=m.id;update galactic_private.rooms set next_match_at=m.ends_at+interval '10 seconds'where id=p_room;changed:=true;end if;
   end if;
   -- Resolve only sources that actually finished. An unresolved future team is
   -- never treated as a bye, so brackets cannot advance prematurely.
   for w in select * from galactic_private.matches where room_id=p_room and status='waiting'order by round,slot loop
    select * into s1 from galactic_private.matches where id=w.source_home;select * into s2 from galactic_private.matches where id=w.source_away;
    if s1.status in('finished','bye')and s2.status in('finished','bye')then update galactic_private.matches set home_id=s1.winner_id,away_id=s2.winner_id,status=case when s1.winner_id is null or s2.winner_id is null then 'bye'else 'ready'end,winner_id=case when s1.winner_id is null or s2.winner_id is null then coalesce(s1.winner_id,s2.winner_id)end where id=w.id;changed:=true;end if;
   end loop;
   if not exists(select 1 from galactic_private.matches where room_id=p_room and status not in('finished','bye'))then
    select * into m from galactic_private.matches where room_id=p_room order by round desc,slot limit 1;update galactic_private.rooms set phase='finished',winner=m.winner_id,next_match_at=null where id=p_room;changed:=true;exit;
   end if;
   select * into r from galactic_private.rooms where id=p_room;
   if r.next_match_at<=p_now then
    select * into m from galactic_private.matches where room_id=p_room and status='ready'order by round,slot limit 1;
    if m.id is not null then perform galactic_private.make_match(m.id,r.next_match_at);changed:=true;continue;end if;
   end if;exit;
  else exit;end if;
 end loop;
 if changed then update galactic_private.rooms set version=version+1,updated_at=p_now where id=p_room;perform galactic_private.notify_room(p_room);end if;
 return changed;
end;$$;
create or replace function galactic_private.match_view(p_match uuid,p_now timestamptz)returns jsonb language plpgsql stable set search_path='' as $$
declare m galactic_private.matches%rowtype;hm galactic_private.members%rowtype;am galactic_private.members%rowtype;elapsed bigint;events jsonb;last_event jsonb;next_event jsonb;start_ms bigint;playback jsonb;
begin
 select * into m from galactic_private.matches where id=p_match;if m.id is null then return null;end if;
 select * into hm from galactic_private.members where id=m.home_id;select * into am from galactic_private.members where id=m.away_id;
 start_ms:=floor(extract(epoch from m.started_at)*1000);elapsed:=greatest(0,floor(extract(epoch from(p_now-m.started_at))*1000));
 select coalesce(jsonb_agg(e order by i),'[]')into events from jsonb_array_elements(m.timeline)with ordinality q(e,i)where (e->>'atMs')::bigint<=elapsed;
 last_event:=events->(jsonb_array_length(events)-1);
 select e into next_event from jsonb_array_elements(m.timeline)with ordinality q(e,i)where (e->>'atMs')::bigint>elapsed order by i limit 1;
 playback:=jsonb_build_object('minute',coalesce((last_event->>'minute')::int,0),'anchorAt',start_ms+coalesce((last_event->>'untilMs')::bigint,0),'pausedUntil',start_ms+coalesce((last_event->>'untilMs')::bigint,0),'nextMinute',coalesce((next_event->>'minute')::int,(last_event->>'minute')::int,0),'minuteMs',2000);
 return jsonb_build_object('id',m.id,'round',m.round,'slot',m.slot,'status',m.status,'startedAt',m.started_at,'endsAt',case when m.status='finished'then m.ends_at end,'home',jsonb_build_object('id',hm.id,'name',hm.name,'teamName',hm.team_name,'formation',hm.formation,'tactic',hm.tactic,'players',galactic_private.lineup(m.room_id,hm.id)),'away',jsonb_build_object('id',am.id,'name',am.name,'teamName',am.team_name,'formation',am.formation,'tactic',am.tactic,'players',galactic_private.lineup(m.room_id,am.id)),'homeScore',coalesce((last_event->>'homeScore')::int,0),'awayScore',coalesce((last_event->>'awayScore')::int,0),'penalties',case when last_event->>'penaltyHome'is not null then jsonb_build_object('home',last_event->'penaltyHome','away',last_event->'penaltyAway')end,'winner',case when m.status='finished'then m.winner_id end,'events',events,'playback',playback,'stats',m.stats);
end;$$;
create or replace function galactic_private.room_view(p_room uuid,p_uid uuid,p_now timestamptz)returns jsonb language plpgsql stable set search_path='' as $$
declare r galactic_private.rooms%rowtype;members jsonb;picks jsonb;matches jsonb;self_id uuid;
begin
 select * into r from galactic_private.rooms where id=p_room;select id into self_id from galactic_private.members where room_id=p_room and user_id=p_uid;
 if self_id is null then raise exception 'عضو این اتاق نیستی.'using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'name',m.name,'teamName',m.team_name,'formation',m.formation,'tactic',m.tactic,'ready',m.ready,'host',m.user_id=r.host_id,'self',m.user_id=p_uid,'online',m.last_seen>p_now-interval '20 seconds','players',galactic_private.lineup(p_room,m.id))order by m.joined_at,m.id),'[]')into members from galactic_private.members m where m.room_id=p_room;
 select coalesce(jsonb_agg(jsonb_build_object('number',pk.number,'member',pk.member_id,'player',pk.player_id,'slot',pk.slot_id,'automatic',pk.automatic,'at',pk.picked_at)order by pk.number),'[]')into picks from galactic_private.picks pk where pk.room_id=p_room;
 select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'round',m.round,'slot',m.slot,'home',m.home_id,'away',m.away_id,'status',m.status,'winner',case when m.status in('finished','bye')then m.winner_id end,'homeScore',case when m.status='finished'then m.home_score end,'awayScore',case when m.status='finished'then m.away_score end,'penalties',case when m.status='finished'then m.penalties end)order by m.round,m.slot),'[]')into matches from galactic_private.matches m where m.room_id=p_room;
 return jsonb_build_object('id',r.id,'code',r.code,'title',r.title,'public',r.public,'capacity',r.capacity,'phase',r.phase,'version',r.version,'datasetVersion',r.dataset_version,'self',self_id,'host',r.host_id=p_uid,'members',members,'picks',picks,'draftOrder',r.draft_order,'pickNumber',r.pick_number,'turn',case when r.phase='draft'then galactic_private.turn_member(r)end,'pickDeadline',r.pick_deadline,'nextMatchAt',r.next_match_at,'matches',matches,'currentMatch',galactic_private.match_view(r.active_match,p_now),'winner',r.winner,'serverNow',floor(extract(epoch from p_now)*1000));
end;$$;
create or replace function public.galactic_catalog(p_version text default null)returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=galactic_private.require_user();d galactic_private.datasets%rowtype;
begin
 select * into d from galactic_private.datasets where case when p_version is null then active else version=p_version end limit 1;if d.version is null then raise exception 'فهرست بازیکنان هنوز آماده نیست.';end if;
 return jsonb_build_object('version',d.version,'players',d.players,'config',d.config,'sources',d.sources);
end;$$;
create or replace function public.galactic_lobbies()returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=galactic_private.require_user();rooms jsonb;mine jsonb;
begin
 select coalesce(jsonb_agg(x order by x->>'createdAt'desc),'[]')into rooms from(select jsonb_build_object('code',r.code,'title',r.title,'capacity',r.capacity,'count',(select count(*)from galactic_private.members m where m.room_id=r.id),'host',coalesce((select username from public.profiles where id=r.host_id),'بازیکن'),'createdAt',r.created_at)as x from galactic_private.rooms r where r.public and r.phase='lobby'and r.created_at>clock_timestamp()-interval '24 hours'order by r.created_at desc limit 30)t;
 select coalesce(jsonb_agg(x order by x->>'createdAt'desc),'[]')into mine from(select jsonb_build_object('code',r.code,'title',r.title,'phase',r.phase,'createdAt',r.created_at)as x from galactic_private.rooms r join galactic_private.members m on m.room_id=r.id and m.user_id=u where r.phase<>'cancelled'order by r.created_at desc limit 10)t;
 return jsonb_build_object('rooms',rooms,'mine',mine);
end;$$;
create or replace function public.galactic_create(p_title text,p_public boolean default false,p_capacity int default 8)returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=galactic_private.require_user();d text;rid uuid;code text;player_name text;stamp timestamptz:=clock_timestamp();
begin
 if p_title is null or char_length(trim(p_title))not between 2 and 40 or p_title~'[<>[:cntrl:]]'or p_capacity is null or p_capacity not between 2 and 8 then raise exception 'نام اتاق و تعداد بازیکنان را بررسی کن.';end if;
 perform pg_advisory_xact_lock(hashtextextended('galactic:create:'||u::text,0));
 if(select count(*)from galactic_private.rooms where host_id=u and phase in('lobby','draft','tournament'))>=3 then raise exception 'ابتدا یکی از اتاق‌های فعلی را تمام کن.';end if;
 select version into d from galactic_private.datasets where active and jsonb_array_length(players)>=p_capacity*11;
 if d is null then raise exception 'فهرست بازیکنان برای این اتاق کافی نیست.';end if;
 select username into player_name from public.profiles where id=u;if player_name is null then raise exception 'ابتدا پروفایل حساب را تکمیل کن.';end if;
 code:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
 insert into galactic_private.rooms(code,host_id,title,public,capacity,dataset_version)values(code,u,trim(p_title),coalesce(p_public,false),p_capacity,d)returning id into rid;
 insert into galactic_private.members(room_id,user_id,name,team_name)values(rid,u,player_name,'تیم '||left(player_name,25));
 return galactic_private.room_view(rid,u,stamp);
end;$$;
create or replace function public.galactic_join(p_code text)returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=galactic_private.require_user();r galactic_private.rooms%rowtype;player_name text;stamp timestamptz:=clock_timestamp();
begin
 select * into r from galactic_private.rooms where code=upper(regexp_replace(trim(p_code),'[[:space:]-]','','g'))for update;
 if r.id is null then raise exception 'اتاق پیدا نشد.';end if;
 if exists(select 1 from galactic_private.members where room_id=r.id and user_id=u)then return galactic_private.room_view(r.id,u,stamp);end if;
 if r.phase<>'lobby'then raise exception 'انتخاب بازیکنان این اتاق شروع شده است.';end if;
 if(select count(*)from galactic_private.members where room_id=r.id)>=r.capacity then raise exception 'اتاق پر است.';end if;
 select username into player_name from public.profiles where id=u;if player_name is null then raise exception 'ابتدا پروفایل را تکمیل کن.';end if;
 insert into galactic_private.members(room_id,user_id,name,team_name)values(r.id,u,player_name,'تیم '||left(player_name,25));
 update galactic_private.rooms set version=version+1,updated_at=stamp where id=r.id;perform galactic_private.notify_room(r.id);
 return galactic_private.room_view(r.id,u,stamp);
end;$$;
create or replace function public.galactic_room(p_code text)returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=galactic_private.require_user();r galactic_private.rooms%rowtype;stamp timestamptz:=clock_timestamp();
begin
 select * into r from galactic_private.rooms where code=upper(trim(p_code))for update;
 if r.id is null or not exists(select 1 from galactic_private.members where room_id=r.id and user_id=u)then raise exception 'ابتدا با کد دعوت به این اتاق بپیوند.'using errcode='42501';end if;
 update galactic_private.members set last_seen=stamp where room_id=r.id and user_id=u;
 perform galactic_private.advance(r.id,stamp);return galactic_private.room_view(r.id,u,stamp);
end;$$;
create or replace function public.galactic_act(p_code text,p_action jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=galactic_private.require_user();r galactic_private.rooms%rowtype;m galactic_private.members%rowtype;d galactic_private.datasets%rowtype;stamp timestamptz:=clock_timestamp();kind text:=p_action->>'type';f text;t text;v_team_name text;slot text;pid text;who uuid;order_ids jsonb;result jsonb;
begin
 select * into r from galactic_private.rooms where code=upper(trim(p_code))for update;
 if r.id is null then raise exception 'اتاق پیدا نشد.';end if;select * into m from galactic_private.members where room_id=r.id and user_id=u;
 if m.id is null then raise exception 'عضو این اتاق نیستی.'using errcode='42501';end if;
 perform galactic_private.advance(r.id,stamp);select * into r from galactic_private.rooms where id=r.id;select * into d from galactic_private.datasets where version=r.dataset_version;
 if kind='setup'then
  if r.phase<>'lobby'then raise exception 'چیدمان و تاکتیک قفل شده‌اند.';end if;
  f:=p_action->>'formation';t:=p_action->>'tactic';v_team_name:=trim(p_action->>'teamName');
  if f is null or t is null or not(d.config->'formations')?f or not(d.config->'tactics')?t or v_team_name is null or char_length(v_team_name)not between 2 and 30 or v_team_name~'[<>[:cntrl:]]'then raise exception 'آرایش، تاکتیک و نام تیم را بررسی کن.';end if;
  update galactic_private.members set formation=f,tactic=t,team_name=v_team_name,ready=coalesce((p_action->>'ready')::boolean,false),last_seen=stamp where id=m.id;
 elsif kind='start'then
  if r.host_id<>u or r.phase<>'lobby'then raise exception 'شروع بازی فقط با میزبان است.';end if;
  if(select count(*)from galactic_private.members where room_id=r.id)<2 or exists(select 1 from galactic_private.members where room_id=r.id and not ready)then raise exception 'حداقل دو بازیکن و آمادگی همهٔ تیم‌ها لازم است.';end if;
  select jsonb_agg(mm.id order by galactic_private.random_value(r.seed||':draft:'||mm.id,1))into order_ids from galactic_private.members mm where mm.room_id=r.id;
  update galactic_private.rooms set phase='draft',draft_order=order_ids,pick_deadline=stamp+interval '60 seconds'where id=r.id;
 elsif kind='pick'then
  if r.phase<>'draft'or p_action->>'pickNumber'is null or(p_action->>'pickNumber')::int<>r.pick_number or galactic_private.turn_member(r)<>m.id then return galactic_private.room_view(r.id,u,stamp)||jsonb_build_object('notice','نوبت تغییر کرده است؛ وضعیت تازه را ببین.');end if;
  pid:=p_action->>'player';slot:=p_action->>'slot';
  if not exists(select 1 from jsonb_array_elements(d.players)p where p->>'id'=pid)or not exists(select 1 from jsonb_array_elements(d.config#>array['formations',m.formation,'slots'])s where s->>'id'=slot)then raise exception 'بازیکن یا جایگاه معتبر نیست.';end if;
  if exists(select 1 from galactic_private.picks where room_id=r.id and player_id=pid)or exists(select 1 from galactic_private.picks where room_id=r.id and member_id=m.id and slot_id=slot)then raise exception 'این بازیکن یا جایگاه قبلاً انتخاب شده است.';end if;
  perform galactic_private.do_pick(r.id,m.id,pid,slot,false,stamp);
 elsif kind in('leave','kick')then
  if r.phase<>'lobby'then raise exception 'پس از شروع، تیم حفظ می‌شود و انتخاب‌های غایب خودکارند.';end if;
  who:=case when kind='leave'then m.id else nullif(p_action->>'member','')::uuid end;
  if kind='kick'and(r.host_id<>u or who=m.id)then raise exception 'این کار فقط با میزبان است.';end if;
  delete from galactic_private.members where room_id=r.id and id=who;
  if not exists(select 1 from galactic_private.members where room_id=r.id)then update galactic_private.rooms set phase='cancelled'where id=r.id;
  elsif kind='leave'and r.host_id=u then update galactic_private.rooms set host_id=(select user_id from galactic_private.members where room_id=r.id order by joined_at,id limit 1)where id=r.id;end if;
  if kind='leave'then update galactic_private.rooms set version=version+1 where id=r.id;perform galactic_private.notify_room(r.id);return jsonb_build_object('left',true);end if;
 else raise exception 'درخواست معتبر نیست.';end if;
 update galactic_private.rooms set version=version+1,updated_at=stamp where id=r.id;perform galactic_private.notify_room(r.id);
 return galactic_private.room_view(r.id,u,stamp);
end;$$;
create or replace function public.galactic_can_watch(p_topic text)returns boolean language sql stable security definer set search_path='' as $$select auth.uid()is not null and exists(select 1 from galactic_private.rooms r join galactic_private.members m on m.room_id=r.id where 'galactic:'||r.id::text=p_topic and m.user_id=auth.uid())$$;
revoke execute on all functions in schema galactic_private from public,anon,authenticated;
revoke execute on function public.galactic_catalog(text),public.galactic_lobbies(),public.galactic_create(text,boolean,int),public.galactic_join(text),public.galactic_room(text),public.galactic_act(text,jsonb),public.galactic_can_watch(text)from public,anon;
grant execute on function public.galactic_catalog(text),public.galactic_lobbies(),public.galactic_create(text,boolean,int),public.galactic_join(text),public.galactic_room(text),public.galactic_act(text,jsonb),public.galactic_can_watch(text)to authenticated;

-- Private, receive-only room notifications. Polling remains a fallback.
DO $policy$ BEGIN
 if to_regclass('realtime.messages')is not null then
  execute 'drop policy if exists galactic_members_receive on realtime.messages';
  execute 'create policy galactic_members_receive on realtime.messages for select to authenticated using (public.galactic_can_watch((select realtime.topic())))';
 end if;
END $policy$;

